-- PRODUCTION RLS: candidates see only their own account/results; active tests/folders are public-read only to authenticated candidates.
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;ALTER TABLE folders ENABLE ROW LEVEL SECURITY;ALTER TABLE tests ENABLE ROW LEVEL SECURITY;ALTER TABLE attempts ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public Read Access for Active Tests" ON tests;DROP POLICY IF EXISTS "Admin Full Access on Tests" ON tests;DROP POLICY IF EXISTS "Public Insert Access for Attempts" ON attempts;DROP POLICY IF EXISTS "Public Read Access for Leaderboard" ON attempts;
DROP POLICY IF EXISTS profiles_self_select ON profiles;DROP POLICY IF EXISTS profiles_self_update ON profiles;DROP POLICY IF EXISTS profiles_admin_all ON profiles;DROP POLICY IF EXISTS folders_candidate_select ON folders;DROP POLICY IF EXISTS folders_admin_all ON folders;DROP POLICY IF EXISTS tests_candidate_select ON tests;DROP POLICY IF EXISTS tests_admin_all ON tests;DROP POLICY IF EXISTS attempts_self_select ON attempts;DROP POLICY IF EXISTS attempts_self_insert ON attempts;DROP POLICY IF EXISTS attempts_admin_select ON attempts;
CREATE POLICY profiles_self_select ON profiles FOR SELECT TO authenticated USING(id=auth.uid());CREATE POLICY profiles_self_update ON profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());CREATE POLICY profiles_admin_all ON profiles FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM profiles p WHERE p.id=auth.uid() AND p.role='admin')) WITH CHECK(EXISTS(SELECT 1 FROM profiles p WHERE p.id=auth.uid() AND p.role='admin'));
CREATE POLICY folders_candidate_select ON folders FOR SELECT TO authenticated USING(active=true);CREATE POLICY folders_admin_all ON folders FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM profiles p WHERE p.id=auth.uid() AND p.role='admin')) WITH CHECK(EXISTS(SELECT 1 FROM profiles p WHERE p.id=auth.uid() AND p.role='admin'));
CREATE POLICY tests_candidate_select ON tests FOR SELECT TO authenticated USING(active=true);CREATE POLICY tests_admin_all ON tests FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM profiles p WHERE p.id=auth.uid() AND p.role='admin')) WITH CHECK(EXISTS(SELECT 1 FROM profiles p WHERE p.id=auth.uid() AND p.role='admin'));
CREATE POLICY attempts_self_select ON attempts FOR SELECT TO authenticated USING(user_id=auth.uid());CREATE POLICY attempts_self_insert ON attempts FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());CREATE POLICY attempts_admin_select ON attempts FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM profiles p WHERE p.id=auth.uid() AND p.role='admin'));
